"""Build the Zanzibar collection from the shared catalogue; no runtime dependency."""
import build_tours as site

GROUPS=[
 ('ocean-days','THE INDIAN OCEAN','Sandbanks, reefs<br>and quiet boat mornings.','Choose the departure coast first. Nakupenda and Changuu leave from Stone Town, Mnemba from Matemwe, and Blue Lagoon from Michamvi. Hotel transfers are extra on these day tours.',['nakupenda-sandbank','blue-lagoon-snorkeling','mnemba-waters-snorkeling','changuu-prison-island','kizimkazi-dolphin-watching']),
 ('island-life','BEYOND THE BEACH','Stone lanes. Spice plants.<br>Forest and freshwater.','Short visits with local guides and hosts. Each activity has a named meeting point; combine nearby stops with one transfer quote instead of booking several separate journeys.',['stone-town-walking-tour','zanzibar-spice-farm','jozani-forest','kuza-cave']),
 ('water-sports','YOUR PACE ON THE WATER','A paddle, a ride<br>or your first ocean dive.','Choose the equipment and session that suit you. Kayaking follows the tide, jet skis use a defined riding slot, and introductory diving starts with instructor assessment.',['zanzibar-mangrove-kayaking','zanzibar-jet-ski','zanzibar-discover-scuba'])]

def rail(ids,label):
    return f'''<div class="island-tour-rail" data-tour-rail><div class="rail-toolbar"><p class="rail-footnote">Automatic tour browsing · pause to take your time</p><div class="rail-buttons" hidden><span class="rail-position" aria-hidden="true">01 / {len(ids):02}</span><button type="button" data-rail-prev aria-label="Show previous {label}">←</button><button type="button" data-rail-next aria-label="Show next {label}">→</button><button type="button" data-rail-pause aria-pressed="false">Pause tours</button></div></div><div class="tour-rail-track" tabindex="0" role="region" aria-label="{label}. Scroll horizontally or use the tour controls.">{site.selected_cards(ids)}</div><p class="sr-only" data-rail-status role="status"></p></div>'''

def build():
    scenes=[('images/zanzibar-tours/jambiani-beach.webp','Beach and turquoise water at Jambiani, Zanzibar','JAMBIANI / THE EAST COAST'),('images/zanzibar-tours/jozani-colobus.webp','Zanzibar red colobus in Jozani Forest','JOZANI / THE ISLAND’S FOREST'),('images/zanzibar-tours/mnemba-island.webp','Reef fish and the island of Mnemba viewed from the surrounding water','MNEMBA / REEF WATERS')]
    frames=''.join(f'<figure data-slide class="{("is-active" if n==0 else "")}" aria-hidden="{str(n!=0).lower()}"{(" inert" if n else "")}>{site.img(image,alt,n==0,"100vw")}<figcaption>{caption}</figcaption></figure>' for n,(image,alt,caption) in enumerate(scenes))
    body=f'''<section class="daytrip-hero island-hero" data-carousel role="region" aria-roledescription="carousel" aria-label="Zanzibar coast and forest photographs"><div class="hero-frames">{frames}</div><div class="daytrip-hero-content"><p class="eyebrow">ZANZIBAR · STONE TOWN · THE COAST</p><h1>Let the island<br>set the pace.<span>Find your Zanzibar.</span></h1><p>A morning among spice plants. A boat timed to the tide. A few days between Stone Town and the coast. Explore the island with a practical plan and room to enjoy it.</p><div class="hero-buttons"><a class="btn btn-primary" href="#ocean-days">Explore island experiences ↗</a><a class="btn btn-secondary" href="#island-stay">Plan six days in Zanzibar</a></div></div><p class="gallery-caption" data-visible-caption>{scenes[0][2]}</p>{site.controls(len(scenes))}</section><div class="daytrip-navigation island-navigation"><p>Clear meeting points · guide prices in USD</p><div><a href="#ocean-days">Boat &amp; reef days</a><a href="#island-life">Culture &amp; nature</a><a href="#water-sports">Water sports</a><a href="#island-stay">Six-day stay</a><a href="#pick-your-coast">Choose your coast</a></div></div>'''
    body+='''<section class="section island-introduction"><div><p class="eyebrow">YOUR ISLAND, THOUGHTFULLY PLANNED</p><h2>Start with where<br>you’re staying.</h2></div><div><p>Zanzibar is more than one departure beach. Your hotel location, tide window and preferred pace determine what fits comfortably into a day.</p><p>Most excursion prices below start at the activity meeting point. Share your hotel for an itemised return-transfer quote; the six-day package includes its listed transfers.</p></div><a class="text-link" href="index.html?trip=zanzibar#contact">Tell David your hotel and dates ↗</a></section>'''
    for id,eyebrow,title,intro,ids in GROUPS:
        body+=f'<section class="section island-collection" id="{id}"><div class="section-heading split-heading"><div><p class="eyebrow">{eyebrow}</p><h2>{title}</h2></div><p>{intro}</p></div>{rail(ids,site.esc(id.replace("-"," ")))}</section>'
    stay=next(t for t in site.TOURS if t['id']=='6-day-zanzibar-island-escape')
    body+=f'''<section class="section island-stay" id="island-stay"><div class="island-stay-image">{site.img(stay['image'],site.image_alt(stay))}<p>Five nights. Two sides of the island.</p></div><div class="island-stay-content"><p class="eyebrow">6 DAYS / 5 NIGHTS · FROM USD 690 PER ADULT</p><h2>Stone Town first.<br>Coast time after.</h2><p>Two nights in Stone Town, then three at the coast. Explore the old town and spice plants, visit Jozani and take a tide-planned Nakupenda day before a free day by the sea.</p><ol class="island-stay-route"><li><strong>Days 1–2</strong><span>Arrive · Stone Town · spice farm</span></li><li><strong>Days 3–4</strong><span>Jozani · coast stay · sandbank picnic</span></li><li><strong>Days 5–6</strong><span>Free coast day · departure transfer</span></li></ol><p class="island-price-note">Off-peak estimate for two adults sharing a simple guesthouse room. Five breakfasts, one picnic and listed transfers are included. Flights, unlisted meals and visitor levies need their own place in your quote.</p><div class="hero-buttons"><a class="btn btn-primary" href="6-day-zanzibar-island-escape.html">See the six-day itinerary ↗</a><a class="text-link" href="index.html?package=6-day-zanzibar-island-escape#contact">Ask about my dates ↗</a></div></div></section>'''
    body+='<section class="section island-special-stay"><p class="eyebrow">A LITTLE LONGER ON THE ISLAND</p><h2>Seven days of culture &amp; coast.</h2><p>Choose a tailored plan with two Stone Town nights, four coastal nights and guided history, spice and forest visits. Optional boat days are quoted around your chosen hotel and sea conditions.</p><a class="btn btn-primary" href="7-day-zanzibar-culture-coast.html">Explore the seven-day special journey ↗</a><a class="text-link" href="zanzibar-coast-tides.html">Read the coast and tides guide ↗</a></section>'
    body+='''<section class="section island-zones" id="pick-your-coast"><div class="section-heading split-heading"><div><p class="eyebrow">LESS BACKTRACKING. MORE ISLAND TIME.</p><h2>Make the day<br>fit the coast.</h2></div><p>Choose a nearby experience, or combine stops along one transfer route. Final pickup times are agreed after your hotel, tide window and activity availability are known.</p></div><div class="island-zone-grid"><article><span class="eyebrow">WEST / STONE TOWN</span><h3>History, spice plants &amp; sandbanks</h3><p>Stone Town is the departure base for Changuu and Nakupenda. Combine a town walk with the spice farm when the transfer route fits.</p><a href="stone-town-walking-tour.html">Start with Stone Town ↗</a></article><article><span class="eyebrow">EAST / PAJE · JAMBIANI · MICHAMVI</span><h3>Reef water, caves &amp; forest</h3><p>Blue Lagoon uses a Michamvi launch. Kuza Cave is near Jambiani; Jozani can sit on the transfer route when the schedule allows.</p><a href="blue-lagoon-snorkeling.html">Explore the east-coast reef trip ↗</a></article><article><span class="eyebrow">NORTH-EAST / MATEMWE</span><h3>Mnemba’s surrounding waters</h3><p>Start the Mnemba snorkeling tour from Matemwe. A north-coast hotel does not automatically include transport to Stone Town or south-coast activities.</p><a href="mnemba-waters-snorkeling.html">See the Mnemba trip ↗</a></article><article><span class="eyebrow">SOUTH / KIZIMKAZI</span><h3>A quiet wildlife morning</h3><p>Meet in Kizimkazi for boat-based dolphin observation. Add Jozani only if the road plan and park visiting time allow it.</p><a href="kizimkazi-dolphin-watching.html">Read the observation approach ↗</a></article></div></section>'''
    tours=[t for t in site.TOURS if t['category']=='zanzibar']
    rows=''.join(f'<tr><th scope="row"><a href="{t["id"]}.html">{site.esc(t["title"])}</a></th><td>{site.esc(t["duration"])}</td><td>{site.esc(t["start"].split(" → ")[0])}</td><td>{site.money(t["price"]) if t["price"] is not None else "Personal quote"}</td><td>{site.esc(t["basis"])}</td></tr>' for t in tours)
    body+=f'''<section class="section island-essentials"><div class="section-heading"><p class="eyebrow">ALL THE ESSENTIALS, TOGETHER</p><h2>Compare your Zanzibar experiences.</h2><p>Estimates per international adult. Day-tour hotel transfers are extra; each itinerary lists its activity, equipment, fees and food inclusions.</p></div><div class="route-comparison-table" role="region" tabindex="0" aria-label="Zanzibar tour comparison, scroll horizontally on small screens"><table><caption>Duration, departure and guide-price basis</caption><thead><tr><th scope="col">Experience</th><th scope="col">Duration</th><th scope="col">Meeting point</th><th scope="col">From / adult</th><th scope="col">Price basis</th></tr></thead><tbody>{rows}</tbody></table></div>{site.EXPLAIN}<div class="island-planning-faq"><details><summary>Can I combine two activities in one day?</summary><p>Yes. Stone Town with a spice visit, or Jozani with Kuza Cave, can be practical starting ideas. David checks the transfer route, opening times and your pace before quoting; separate card prices do not include a combined transfer automatically.</p></details><details><summary>What happens when the sea is unsuitable?</summary><p>The captain or activity provider decides whether it is safe to depart. Before payment, your written quote must state the rescheduling and refund terms for weather-related changes. Keep some flexibility around ocean days.</p></details><details><summary>Is the clear kayak included at USD 45?</summary><p>No. USD 45 is the standard mangrove kayak estimate. A transparent kayak starts at an estimated USD 60 per adult, with venue, equipment and availability confirmed separately.</p></details><details><summary>Are dolphins, reef visibility or an exact hotel guaranteed?</summary><p>Wildlife and visibility vary. The six-day package uses named guesthouses confirmed for your dates; no hotel is held automatically by viewing the website. The written itinerary confirms the actual services.</p></details></div></section>'''
    body+='''<section class="section destination-final-cta island-final"><p class="eyebrow">LET’S MAKE YOUR ISLAND PLAN</p><h2>Send your hotel.<br>Bring your ideas.</h2><p>Share your dates, group, hotel and the experiences you like. David will put the activities, transfers and complete price into one practical plan.</p><a class="btn btn-primary" href="index.html?trip=zanzibar#contact">Plan Zanzibar with David ↗</a><p class="photo-note">Licensed destination and activity photographs; captions identify illustrative images. <a href="photo-credits.html">Photographers, sources and licences</a></p></section>'''
    schema={'@context':'https://schema.org','@type':'ItemList','name':'David Explora Zanzibar experiences','itemListElement':[{'@type':'ListItem','position':i+1,'name':t['title'],'url':site.ORIGIN+'/'+t['id']+'.html'} for i,t in enumerate(tours)]}
    site.page('zanzibar.html','Zanzibar Tours, Ocean Days & 6-Day Island Stays','Explore Zanzibar sandbanks, guided snorkeling, Stone Town, Jozani, spice farms, kayaking, Kuza Cave and a six-day island stay. Compare clear meeting points and guide prices.',body,scenes[0][0],schema)
    home=site.ROOT/'index.html';text=home.read_text(encoding='utf-8')
    selected=['nakupenda-sandbank','jozani-forest','blue-lagoon-snorkeling','6-day-zanzibar-island-escape','kuza-cave','zanzibar-mangrove-kayaking']
    import re
    text=re.sub(r'<!-- BEGIN: home-zanzibar -->.*?<!-- END: home-zanzibar -->',lambda _: '<!-- BEGIN: home-zanzibar -->'+rail(selected,'Zanzibar experiences')+'<!-- END: home-zanzibar -->',text,flags=re.S)
    home.write_text(text, encoding='utf-8')
    site.sitemap()
    print('Built Zanzibar island hub and home experience slider')

if __name__=='__main__':build()
